func (this *Btcmarkets) ParseTrade(trade any, optionalArgs ...any) any {
	//
	// public fetchTrades
	//
	//     {
	//         "id":"6191646611",
	//         "price":"539.98",
	//         "amount":"0.5",
	//         "timestamp":"2020-08-09T15:21:05.016000Z",
	//         "side":"Ask"
	//     }
	//
	// private fetchMyTrades
	//
	//     {
	//         "id": "36014819",
	//         "marketId": "XRP-AUD",
	//         "timestamp": "2019-06-25T16:01:02.977000Z",
	//         "price": "0.67",
	//         "amount": "1.50533262",
	//         "side": "Ask",
	//         "fee": "0.00857285",
	//         "orderId": "3648306",
	//         "liquidityType": "Taker",
	//         "clientOrderId": "48"
	//     }
	//
	market := GetArg(optionalArgs, 0, nil)
	_ = market
	var timestamp any = this.Parse8601(this.SafeString(trade, "timestamp"))
	var marketId any = this.SafeString(trade, "marketId")
	market = this.SafeMarket(marketId, market, "-")
	var feeCurrencyCode any = Ternary(IsTrue((IsEqual(GetValue(market, "quote"), "AUD"))), GetValue(market, "quote"), GetValue(market, "base"))
	var side any = this.SafeString(trade, "side")
	if IsTrue(IsEqual(side, "Bid")) {
		side = "buy"
	} else if IsTrue(IsEqual(side, "Ask")) {
		side = "sell"
	}
	var id any = this.SafeString(trade, "id")
	var priceString any = this.SafeString(trade, "price")
	var amountString any = this.SafeString(trade, "amount")
	var orderId any = this.SafeString(trade, "orderId")
	var fee any = nil
	var feeCostString any = this.SafeString(trade, "fee")
	if IsTrue(!IsEqual(feeCostString, nil)) {
		fee = map[string]any{
			"cost":     feeCostString,
			"currency": feeCurrencyCode,
		}
	}
	var takerOrMaker any = this.SafeStringLower(trade, "liquidityType")
	return this.SafeTrade(map[string]any{
		"info":         trade,
		"id":           id,
		"timestamp":    timestamp,
		"datetime":     this.Iso8601(timestamp),
		"order":        orderId,
		"symbol":       GetValue(market, "symbol"),
		"type":         nil,
		"side":         side,
		"price":        priceString,
		"amount":       amountString,
		"cost":         nil,
		"takerOrMaker": takerOrMaker,
		"fee":          fee,
	}, market)
}

